class Dikdortgen {
    protected int genislik, yukseklik;
    public void setGenislik(int g) { genislik = g; }
    public void setYukseklik(int y) { yukseklik = y; }
    public int alan() { return genislik * yukseklik; }
}

class Kare extends Dikdortgen {
    @Override public void setGenislik(int g) { genislik = g; yukseklik = g; }
    @Override public void setYukseklik(int y) { genislik = y; yukseklik = y; }
}

public class Main {
    static int olcumYap(Dikdortgen d) {
        d.setGenislik(5);
        d.setYukseklik(4);
        return d.alan();
    }
    public static void main(String[] args) {
        System.out.println(olcumYap(new Dikdortgen()));
        System.out.println(olcumYap(new Kare()));
        System.out.println(olcumYap(new Dikdortgen()) == 20);
        System.out.println(olcumYap(new Kare()) == 20);
    }
}

import java.util.*;

interface SiparisDepo {
    void kaydet(String no);
    int adet();
}

class BellekDepo implements SiparisDepo {
    private List<String> kayitlar = new ArrayList<>();
    public void kaydet(String no) { kayitlar.add(no); System.out.println("bellek: " + no); }
    public int adet() { return kayitlar.size(); }
}

class LogDepo implements SiparisDepo {
    private SiparisDepo ic;
    private int sayac = 0;
    LogDepo(SiparisDepo ic) { this.ic = ic; }
    public void kaydet(String no) { sayac++; System.out.println("log #" + sayac); ic.kaydet(no); }
    public int adet() { return ic.adet(); }
}

class SiparisServisi {
    private final SiparisDepo depo;
    SiparisServisi(SiparisDepo depo) { this.depo = depo; }
    void olustur(String no) { depo.kaydet(no); }
    int toplam() { return depo.adet(); }
}

public class Main {
    public static void main(String[] args) {
        SiparisServisi s = new SiparisServisi(new LogDepo(new BellekDepo()));
        s.olustur("S1");
        s.olustur("S2");
        System.out.println("toplam=" + s.toplam());
    }
}

import java.util.*;

interface Kargo {
    void tasi(String paket);
}

class Yurtici implements Kargo {
    public void tasi(String p) { System.out.println("yurtici: " + p); }
}

class Depo implements Kargo {
    public void tasi(String p) { throw new UnsupportedOperationException("depo tasimaz"); }
}

public class Main {
    static void gonder(List<Kargo> liste, String paket) {
        for (Kargo k : liste) {
            try {
                k.tasi(paket);
            } catch (UnsupportedOperationException e) {
                System.out.println("hata: " + e.getMessage());
            }
        }
    }
    public static void main(String[] args) {
        List<Kargo> liste = new ArrayList<>(List.of(new Yurtici(), new Depo()));
        gonder(liste, "P1");
        System.out.println("adet=" + liste.size());
    }
}

