interface Kahve {
    double fiyat();
    String ad();
}

class Espresso implements Kahve {
    public double fiyat() { return 8.0; }
    public String ad() { return "Espresso"; }
}

abstract class Sos implements Kahve {
    protected Kahve ic;
    Sos(Kahve ic) { this.ic = ic; }
}

class Sut extends Sos {
    Sut(Kahve ic) { super(ic); }
    public double fiyat() { return ic.fiyat() + 2.5; }
    public String ad() { return ic.ad() + " + sut"; }
}

class Seker extends Sos {
    Seker(Kahve ic) { super(ic); }
    public double fiyat() { return ic.fiyat() + 1.0; }
    public String ad() { return ic.ad() + " + seker"; }
}

public class Main {
    public static void main(String[] args) {
        Kahve k = new Seker(new Seker(new Sut(new Espresso())));
        System.out.println(k.ad());
        System.out.println(k.fiyat());
    }
}

public class Ucgen {
    static String sinifla(int a, int b, int c) {
        if (a <= 0 || b <= 0 || c <= 0) return "GECERSIZ";
        if (a + b < c || a + c < b || b + c < a) return "UCGEN DEGIL";
        if (a == b && b == c) return "ESKENAR";
        if (a == b || b == c || a == c) return "IKIZKENAR";
        return "CESITKENAR";
    }
    public static void main(String[] x) {
        System.out.println(sinifla(3, 3, 3));
        System.out.println(sinifla(10, 10, 20));
        System.out.println(sinifla(1, 2, 3));
        System.out.println(sinifla(0, 4, 5));
        System.out.println(sinifla(5, 8, 5));
    }
}

public class Main {
    static int gecen = 0, kalan = 0;

    static void esit(int beklenen, int gercek, String ad) {
        if (beklenen == gercek) {
            gecen++;
        } else {
            kalan++;
            System.out.println("BASARISIZ " + ad + ": beklenen " + beklenen + " bulunan " + gercek);
        }
    }

    static int indirim(int tutar) {
        if (tutar > 1000) return tutar - tutar * 10 / 100;
        if (tutar > 500)  return tutar - tutar * 5 / 100;
        return tutar;
    }

    public static void main(String[] a) {
        esit(100, indirim(100), "indirimsiz");
        esit(475, indirim(500), "sinir-500");
        esit(950, indirim(999), "999");
        esit(900, indirim(1000), "sinir-1000");
        esit(901, indirim(1001), "1001");
        System.out.println("Gecen: " + gecen + " Kalan: " + kalan);
    }
}
